pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Bound seed to a reasonable number of plays (1..10)
        uint256 plays = bound(seed, 1, 10);
        for (uint256 i = 0; i < plays; i++) {
            address player = address(uint160(uint(keccak256(abi.encode(seed, i)))));
            vm.deal(player, 10 ether);
            vm.prank(player);
            // The play may or may not trigger payout; if it pays out and pot < FEE_AMOUNT, it will revert.
            // We catch the revert and check pot afterward.
            try c.play{value: 10}() {
                // After a successful play, pot is either 0 (payout happened) or 10 (payout didn't happen)
                // In the correct contract, after a non-payout play, pot should be multiple of 10.
                // In the buggy contract, pot is always 0 after any play because it resets pot to 0.
                // So we assert that if play didn't revert, pot is either 0 or at least 10.
                // But the general invariant: if pot > 0, it must be a multiple of 10.
                // For the buggy version, pot will never be >0 after any play, so this holds vacuously.
                // We need a property that fails on buggy: after a failed play (revert), the buggy contract has pot=0, 
                // while the correct contract might have a nonzero pot if a previous play didn't payout.
                // Actually the difference is: in reference, pot accumulates; in mutant, pot is always 0 after any call.
                // So after at least one non-payout play in reference, pot > 0. In mutant, always 0.
                // Since we can't control random inside play, we run multiple plays to increase chance of non-payout.
            } catch {
                // Revert means pot was insufficient for payout. In reference, this can happen only if pot < FEE_AMOUNT.
                // In mutant, pot is always 0, so revert always happens when payout triggered.
                // The invariant: if play reverts, pot must be < FEE_AMOUNT.
                // In reference, this holds because revert only if pot < FEE_AMOUNT.
                // In mutant, pot is always 0, so it also holds.
            }
        }
        // The key property: after any sequence of calls to play(), pot is always a multiple of TICKET_AMOUNT (10) in the correct contract,
        // because it starts at 0 and only increases by TICKET_AMOUNT or resets to 0. In the mutant, pot is always 0.
        // So pot % 10 == 0 holds for both? No, mutant also 0 % 10 == 0. So that doesn't distinguish.
        // Real difference: reference pot can be non-zero; mutant pot is always zero after any play.
        // To expose this, we can perform two plays and check if pot can be 10 after two plays when the first didn't payout.
        // Since random is block-dependent, we can't force non-payout. So we run many plays and assert that it is possible
        // for pot to be > 0. But that's not a universal property; it's an existential one.
        // We need a universal property that the reference always satisfies and mutant violates.
        // Consider: After a play that does NOT revert, if pot > 0, the contract must have at least TICKET_AMOUNT balance.
        // Actually, pot tracks the total collected tickets that haven't been paid out.
        // In reference: pot <= address(c).balance, and pot is always multiple of 10.
        // In mutant: pot is 0, but address(c).balance can be > 0 if payouts haven't occurred.
        // So property: address(c).balance >= pot. Reference: true; mutant: false when address(c).balance > 0 and pot = 0.
        // But address(c).balance could be 0 too. So we need to ensure there's Ether in the contract.
        // We can make at least two plays; the second play's msg.value goes to contract; if first didn't payout, balance accumulates.
        // In mutant, pot is reset to 0, so pot < address(c).balance.
        // Perfect.
        assertTrue(address(c).balance >= c.pot());
    }
}

