import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 playsToWin) public {
        // Ensure at least one losing play happens before we attempt the winning play
        uint256 losingPlays = bound(playsToWin, 1, 100);
        address player = address(0x1234);
        vm.deal(player, (losingPlays + 1) * 10 ether);
        vm.startPrank(player);

        // Execute losing plays (random != 0). We need to ensure they are losing.
        // Since random depends on block.timestamp and difficulty, we can manipulate them.
        // We'll use vm.roll / vm.warp to guarantee losing conditions.
        for (uint256 i = 0; i < losingPlays; i++) {
            // Set block.timestamp and difficulty such that random becomes 1 (odd)
            vm.warp(block.timestamp + 1);
            vm.roll(block.number + 1);
            // Re-set difficulty to make keccak256 produce an odd result
            // We use brute force heuristic: warp until keccak256 % 2 == 1
            // Instead of a loop, we just call play; if it wins, we skip or revert.
            // To guarantee losing, we can't easily without reverting. But the property
            // doesn't require guaranteeing loss, only that pot eventually becomes nonzero.
            // So we just call play and catch revert (only in winning case with pot=0 it may revert).
            // In original, losing plays add 10 to pot.
            try c.play{value: 10}() {} catch { /* ignore reverts */ }
        }

        // Now try a winning play. We need to force random == 0.
        // For simplicity, we just try repeatedly with different timestamps.
        bool ok;
        vm.warp(block.timestamp + 1);
        vm.roll(block.number + 1);
        try c.play{value: 10}() returns (bool) { ok = true; } catch { ok = false; }

        // After a successful winning play, pot must be 0 in both implementations.
        // But in the buggy version, if the previous calls set pot to 0,
        // the winning play will underflow and revert, so ok=false and pot may remain non-zero.
        // The property: if a play succeeds (ok=true) and random==0 (it does not revert),
        // then pot must be 0. But we cannot detect random==0 from outside.
        // Instead, we assert that after any sequence, the invariant holds:
        // pot <= number of successful plays * 10 - payouts? Hard to express.
        // Let's use a different approach: after the final call, we measure pot and whether it reverted.
        // In original: after a winning play, pot becomes 0 (no revert).
        // In mutant: after first play, pot=0; next play sets pot=0 again (no-op);
        // if that play is a winner, it tries pot - FEE_AMOUNT which underflows, causing revert.
        // So we check: if the final call did not revert, then pot must be 0.
        // This is true in original because winning always zeros pot, losing keeps nonzero.
        // In mutant: after first call, pot is 0; if next call is a loser, it sets pot=0 again, ok true, pot 0.
        // So it still holds. We need a case where pot is nonzero and call succeeds.
        // In mutant: pot is always 0 after every play, so pot can never be >0.
        // In original: after losing plays, pot > 0; a subsequent losing play keeps pot >0.
        // So property: pot can be > 0 after a successful play.
        // In mutant: pot is always 0 after any successful play, so this fails.
        assertTrue(ok && c.pot() > 0);
    }
}

