pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 r) public {
        // r determines the sequence of random outcomes
        // We simulate block.timestamp and block.difficulty to control keccak256
        // We need at least two calls to observe the difference:
        // - first call to build up pot
        // - second call that wins and pays out
        // The bug prevents pot from growing, so the payout is only FEE_AMOUNT instead of accumulated pot.

        // We use the fuzzed r to set block.timestamp and block.difficulty such that
        // the first call is non-winning (random != 0) and the second call is winning (random == 0).
        // The exact mapping: random = uint(keccak256(abi.encodePacked(timestamp, difficulty))) % 2
        // We set timestamp = 1 and difficulty = r such that result % 2 == 1 for first, and % 2 == 0 for second.

        // First call setup: non-winning
        vm.warp(1);
        vm.roll(uint256(keccak256(abi.encode(r | 0x80))) & 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF); // arbitrary difficulty
        // Adjust difficulty so that (keccak256(abi.encodePacked(1, difficulty)) % 2) != 0
        // We can just pick a difficulty that makes it odd by trial in the fuzz, but easier: set difficulty to 1,
        // but we need the fuzzer to find a combination where two calls differ. We'll let the fuzzer explore.

        // Instead, we make two separate calls with different fuzzed timestamps and difficulties.
        // We receive two fuzzed values: r is used to derive two sets of (timestamp, difficulty) that produce different random outcomes.
        uint256 ts1 = uint256(r) & 0x0F;
        uint256 ts2 = uint256(r) >> 4;

        // We need ts1 != ts2 and difficulties that yield different randoms.
        vm.assume(ts1 != ts2);

        address player1 = makeAddr("player1");
        address player2 = makeAddr("player2");
        vm.deal(player1, 10 ether);
        vm.deal(player2, 10 ether);

        // Call 1 (non-winning)
        vm.warp(ts1);
        vm.roll(1);
        // We need the first call to not win (random != 0)
        uint random1 = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        vm.assume(random1 != 0);
        vm.prank(player1);
        c.play{value: 10}();

        // Call 2 (winning)
        vm.warp(ts2);
        vm.roll(2);
        vm.assume(ts2 != ts1);
        uint random2 = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        vm.assume(random2 == 0);

        // Record player2 balance before winning call
        uint256 balBefore = player2.balance;
        vm.prank(player2);
        c.play{value: 10}();

        // After a winning call, the pot is reset to 0 and the winner should receive pot - FEE_AMOUNT
        // In the reference, pot was accumulated from both calls: pot = 20, winner receives 20 - 1 = 19.
        // In the buggy, pot stays 0 after first call, then second call adds 0, pot = 0, winner receives 0 - 1 (underflow) or pot - FEE_AMOUNT reverts.
        // We capture the actual transfer by checking player2's balance change.
        // Reference: player2 receives 19 ether (minus gas). Buggy: transfer reverts or sends 0.

        uint256 balAfter = player2.balance;
        // The invariant: after a winning play, the winner's balance increase must be exactly the total ticket amounts minus fee.
        // Total tickets = 2 * 10 = 20, fee = 1, expected payout = 19.
        // In reference, this holds. In buggy, the payout is less (or reverts).
        assertTrue(balAfter - balBefore == 19);
    }
}

